#include <stdio.h>
#include <string.h>

#define INF 1000000000

int main() {
    char s[100005];
    while (scanf("%s", s) == 1) {
        int n = strlen(s);
        // dp[foot] = min violations ending with that foot (0=Left, 1=Right)
        int dp[2];
        int ndp[2];

        // First arrow
        char c = s[0];
        if (c == 'L') {
            dp[0] = 0; dp[1] = INF;
        } else if (c == 'R') {
            dp[0] = INF; dp[1] = 0;
        } else {
            dp[0] = 0; dp[1] = 0;
        }

        for (int i = 1; i < n; i++) {
            c = s[i];
            ndp[0] = INF; ndp[1] = INF;

            // Try assigning left foot (0)
            if (c == 'L' || c == 'U' || c == 'D') {
                // use left foot
                int cost0 = dp[0] + 1; // violation: prev was left
                int cost1 = dp[1] + 0; // no violation: prev was right
                int best = cost0 < cost1 ? cost0 : cost1;
                if (best < ndp[0]) ndp[0] = best;
            }

            // Try assigning right foot (1)
            if (c == 'R' || c == 'U' || c == 'D') {
                // use right foot
                int cost0 = dp[0] + 0; // no violation: prev was left
                int cost1 = dp[1] + 1; // violation: prev was right
                int best = cost0 < cost1 ? cost0 : cost1;
                if (best < ndp[1]) ndp[1] = best;
            }

            dp[0] = ndp[0];
            dp[1] = ndp[1];
        }

        int ans = dp[0] < dp[1] ? dp[0] : dp[1];
        printf("%d\n", ans);
    }
    return 0;
}

#include <stdio.h>
