#define INF 1000000000

static int dir_id(const char *s) {
    if (strcmp(s, "U") == 0 || strcmp(s, "up") == 0 || strcmp(s, "Up") == 0) return 0;
    if (strcmp(s, "D") == 0 || strcmp(s, "down") == 0 || strcmp(s, "Down") == 0) return 1;
    if (strcmp(s, "L") == 0 || strcmp(s, "left") == 0 || strcmp(s, "Left") == 0) return 2;
    return 3; // R / right
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *a = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        char s[32];
        scanf("%s", s);
        a[i] = dir_id(s);
    }

    /* dp[l][r][t]:
       minimal violations after processing some prefix,
       with left foot on l, right foot on r,
       and t = 0 means last step used left foot, t = 1 means right foot.
       Positions: 0=U,1=D,2=L,3=R, 4=unused/not placed yet.
    */
    static int dp[5][5][2], ndp[5][5][2];

    for (int l = 0; l < 5; l++)
        for (int r = 0; r < 5; r++)
            for (int t = 0; t < 2; t++)
                dp[l][r][t] = INF;

    int first = a[0];
    dp[first][4][0] = 0; // first arrow with left foot
    dp[4][first][1] = 0; // first arrow with right foot

    for (int i = 1; i < n; i++) {
        for (int l = 0; l < 5; l++)
            for (int r = 0; r < 5; r++)
                for (int t = 0; t < 2; t++)
                    ndp[l][r][t] = INF;

        int x = a[i];
        for (int l = 0; l < 5; l++) {
            for (int r = 0; r < 5; r++) {
                for (int t = 0; t < 2; t++) {
                    int cur = dp[l][r][t];
                    if (cur >= INF) continue;

                    /* Use left foot */
                    if (x != r) {
                        int add = (t == 0); // same foot twice => violation
                        if (cur + add < ndp[x][r][0])
                            ndp[x][r][0] = cur + add;
                    }

                    /* Use right foot */
                    if (x != l) {
                        int add = (t == 1); // same foot twice => violation
                        if (cur + add < ndp[l][x][1])
                            ndp[l][x][1] = cur + add;
                    }
                }
            }
        }

        for (int l = 0; l < 5; l++)
            for (int r = 0; r < 5; r++)
                for (int t = 0; t < 2; t++)
                    dp[l][r][t] = ndp[l][r][t];
    }

    int ans = INF;
    for (int l = 0; l < 5; l++)
        for (int r = 0; r < 5; r++)
            for (int t = 0; t < 2; t++)
                if (dp[l][r][t] < ans) ans = dp[l][r][t];

    printf("%d\n", ans);

    free(a);
    return 0;
}

