    int violations_start_right = 0;

    // Simulate starting with left foot
    char current_foot = 'L';
    for (char arrow : s) {
        if (arrow != current_foot) {
            violations_start_left++;
        }
        current_foot = (current_foot == 'L') ? 'R' : 'L';
    }

    // Simulate starting with right foot
    current_foot = 'R';
    for (char arrow : s) {
        if (arrow != current_foot) {
            violations_start_right++;
        }
        current_foot = (current_foot == 'L') ? 'R' : 'L';
    }

    cout << min(violations_start_left, violations_start_right) << '\n';

    return 0;
}

