#include <bits/stdc++.h>
using namespace std;

static int id(char c) {
    if (c == 'L') return 0;
    if (c == 'U') return 1;
    if (c == 'D') return 2;
    return 3; // 'R'
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    if (!(cin >> s)) return 0;

    const int INF = 1e9;
    int n = (int)s.size();

    // dp[l][r]: minimum violations after processing current prefix,
    // with left foot on l and right foot on r.
    // Positions: 0=L,1=U,2=D,3=R,4=free(not placed yet)
    vector<vector<int>> dp(5, vector<int>(5, INF)), ndp(5, vector<int>(5, INF));
    dp[4][4] = 0;

    for (char c : s) {
        int x = id(c);
        for (int i = 0; i < 5; ++i)
            for (int j = 0; j < 5; ++j)
                ndp[i][j] = INF;

        for (int l = 0; l < 5; ++l) {
            for (int r = 0; r < 5; ++r) {
                if (dp[l][r] == INF) continue;

                // Use left foot
                if (x != r) {
                    int add = 0;
                    if (l != 4) {
                        // Natural style:
                        // left foot should not move to the right arrow
                        if (x == 3) add = 1; // R
                    }
                    ndp[x][r] = min(ndp[x][r], dp[l][r] + add);
                }

                // Use right foot
                if (x != l) {
                    int add = 0;
                    if (r != 4) {
                        // Natural style:
                        // right foot should not move to the left arrow
                        if (x == 0) add = 1; // L
                    }
                    ndp[l][x] = min(ndp[l][x], dp[l][r] + add);
                }
            }
        }
        dp.swap(ndp);
    }

    int ans = INF;
    for (int l = 0; l < 5; ++l)
        for (int r = 0; r < 5; ++r)
            ans = min(ans, dp[l][r]);

    cout << ans << '\n';
    return 0;
}

import java.util.Scanner;

public class StepStepEvolution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine().trim();
        sc.close();

        int n = s.length();
        // dp[0] = violations if last foot was left
        // dp[1] = violations if last foot was right
        int dpL = 0, dpR = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int newDpL, newDpR;

            if (c == 'L') {
                // To end with left foot now:
                // - from previous left: violation + 1
                // - from previous right: no violation
                newDpL = Math.min(dpL + 1, dpR);
                // To end with right foot now:
                // impossible because arrow is L, so set to large number
                newDpR = Integer.MAX_VALUE / 2;
            } else if (c == 'R') {
                newDpL = Integer.MAX_VALUE / 2;
                newDpR = Math.min(dpR + 1, dpL);
            } else { // 'U' or 'D'
                newDpL = Math.min(dpL + 1, dpR);
                newDpR = Math.min(dpR + 1, dpL);
            }

            dpL = newDpL;
            dpR = newDpR;
        }

        System.out.println(Math.min(dpL, dpR));
    }
}

