import java.io.*;
import java.util.*;

public class Main {
    static final int INF = 1_000_000_000;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) return;
        s = s.trim();

        // Map directions to indices:
        // L=0, U=1, D=2, R=3
        int[] seq = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == 'L') seq[i] = 0;
            else if (c == 'U') seq[i] = 1;
            else if (c == 'D') seq[i] = 2;
            else seq[i] = 3; // R
        }

        // opposite[d] = opposite arrow
        int[] opposite = {3, 2, 1, 0};

        // dp[l][r]: minimum violations after processing current prefix,
        // with left foot on l and right foot on r.
        // positions are always distinct.
        int[][] dp = new int[4][4];
        for (int i = 0; i < 4; i++) Arrays.fill(dp[i], INF);

        // Initial positions: left foot on L, right foot on R
        dp[0][3] = 0;

        for (int x : seq) {
            int[][] ndp = new int[4][4];
            for (int i = 0; i < 4; i++) Arrays.fill(ndp[i], INF);

            for (int l = 0; l < 4; l++) {
                for (int r = 0; r < 4; r++) {
                    int cur = dp[l][r];
                    if (cur == INF) continue;

                    // Move left foot to x, if right foot not already there
                    if (r != x) {
                        int cost = cur + ((x == opposite[r]) ? 0 : 1);
                        ndp[x][r] = Math.min(ndp[x][r], cost);
                    }

                    // Move right foot to x, if left foot not already there
                    if (l != x) {
                        int cost = cur + ((x == opposite[l]) ? 0 : 1);
                        ndp[l][x] = Math.min(ndp[l][x], cost);
                    }
                }
            }
            dp = ndp;
        }

        int ans = INF;
        for (int l = 0; l < 4; l++) {
            for (int r = 0; r < 4; r++) {
                ans = Math.min(ans, dp[l][r]);
            }
        }

        System.out.println(ans);
    }
}
